trait Updatable { def update(dt: Double): Unit }     // the hook

final class Guard(var x: Double = 0.0) extends Updatable {
  override def update(dt: Double): Unit = x += 20.0 * dt
}

val world: List[Updatable] = List(new Guard)
world.foreach(_.update(dt))                          // the driver walk
